            A.Apply(in x, ref tmpM);
            u.CopyFrom(in b);
            u.addScaledInPlace((float)(-1), tmpM);

            float beta = math.sqrt(Blas.dot(u, u));

            if (beta == (float)0)
                // x already exact (r = 0).
                return LstsqInfoTracked(IterativeSolveStatus.Converged, 0, (float)0, (float)0, (float)0, in x);

            u.divInPlace(beta);

            // v = A^T u ; alpha = ||v||
            A.ApplyT(in u, ref tmpN);
            v.CopyFrom(in tmpN);

            float alpha = math.sqrt(Blas.dot(v, v));

            if (alpha == (float)0)
                // x already least-squares-stationary (A^T r = 0). ‖r‖ = beta.
                return LstsqInfoTracked(IterativeSolveStatus.Converged, 0, beta, (float)0, (float)0, in x);

            v.divInPlace(alpha);

            // ||A^T r_0|| = alpha*beta = |zetabar_1|; matches lsqr's pre-loop early-out.
            if ((alpha * beta) * (alpha * beta) <= threshold)
                return LstsqInfoTracked(IterativeSolveStatus.Converged, 0, beta, alpha * beta, (float)0, in x);

            // h = v ; hbar = 0
            h.CopyFrom(in v);
            for (int i = 0; i < hbar.N; i++) hbar[i] = (float)0;

            // MINRES-on-normal-equations rotation state.
            float alphabar = alpha;
            float zetabar  = alpha * beta;
            float rho = (float)1, rhobar = (float)1, cbar = (float)1, sbar = (float)0;

            // ---- ‖r‖ estimate state (Fong & Saunders 2011, "LSMR" §5.4 / SciPy lsmr). LSMR does
            // not hold the residual r = b - A x, but ‖r‖ falls out of a short scalar recurrence
            // over the SAME rotations at O(1)/iteration -- no extra matvec/dot. beta here is
            // beta1 = ‖b - A x0‖; undamped (damp==0) -> chat==1, shat==0 -> betacheck==0. ----
            float betadd = beta;
            float betad = (float)0;
            float rhodold = (float)1;
            float tautildeold = (float)0;
            float thetatilde = (float)0;
            float zeta = (float)0;
            float dnorm = (float)0;   // accumulates betacheck^2
            float normr = beta;

            for (int k = 0; k < maxIter; k++)
            {
                // ---- bidiagonalization step (Golub-Kahan) ----
                beta = GolubKahanUStep(in A, in v, alpha, ref tmpM, ref u);
                if (beta > (float)0)
                {
                    u.divInPlace(beta);
                    alpha = GolubKahanVStep(in A, in u, beta, ref tmpN, ref v);
                    if (alpha > (float)0) v.divInPlace(alpha);
                }

                // ---- rotation P_k : (alphahat, beta) -> (rho, 0) ----
                // alphahat folds in the Tikhonov damping: alphahat = sqrt(alphabar^2 + damp^2).
                // damp==0 -> alphahat==alphabar exactly, so the undamped path is bit-identical.
                // (chat, shat) is the rotation folding damp -- needed by the ‖r‖ recurrence.
                float rhoold = rho;
                float alphahat = damp != (float)0 ? math.sqrt(alphabar * alphabar + damp * damp) : alphabar;
                float chat, shat;
                if (alphahat > (float)0) { chat = alphabar / alphahat; shat = damp / alphahat; }
                else { chat = (float)1; shat = (float)0; }
                rho = math.sqrt(alphahat * alphahat + beta * beta);
                if (!(rho > (float)0))
                    // breakdown: alphahat and beta both zero. normr/zetabar carry the prior step's values.
                    return LstsqInfoTracked(IterativeSolveStatus.Breakdown, k + 1, normr, math.abs(zetabar), damp, in x);
                float c = alphahat / rho;
                float s = beta / rho;
                float thetanew = s * alpha;
                alphabar = c * alpha;

                // ---- rotation Pbar_k : fold R^T into Rbar (the MINRES layer) ----
                float rhobarold = rhobar;
                float thetabar = sbar * rho;
                float cbarrho = cbar * rho;
                rhobar = math.sqrt(cbarrho * cbarrho + thetanew * thetanew);
                if (!(rhobar > (float)0))
                    return LstsqInfoTracked(IterativeSolveStatus.Breakdown, k + 1, normr, math.abs(zetabar), damp, in x);
                cbar = cbarrho / rhobar;
                sbar = thetanew / rhobar;
                float zetaold = zeta;
                zeta = cbar * zetabar;
                zetabar = -sbar * zetabar;

                // ---- updates: hbar, x, h ----
                // hbar = h - (thetabar*rho / (rhoold*rhobarold)) * hbar
                float coefHbar = thetabar * rho / (rhoold * rhobarold);
                hbar.scaleAddInPlace(-coefHbar, h);           // hbar = -coefHbar*hbar + h
                // x = x + (zeta / (rho*rhobar)) * hbar
                x.addScaledInPlace(zeta / (rho * rhobar), hbar);
                // h = v - (thetanew/rho) * h
                h.scaleAddInPlace(-thetanew / rho, v);         // h = -(thetanew/rho)*h + v

                // ---- ‖r‖ recurrence for the just-updated x (this step's rotations; no matvec) ----
                float betaacute = chat * betadd;
                float betacheck = -shat * betadd;
                float betahat = c * betaacute;
                betadd = -s * betaacute;

                float thetatildeold = thetatilde;
                float rhotildeold = math.sqrt(rhodold * rhodold + thetabar * thetabar);
                float ctildeold = rhotildeold > (float)0 ? rhodold / rhotildeold : (float)1;
                float stildeold = rhotildeold > (float)0 ? thetabar / rhotildeold : (float)0;
                thetatilde = stildeold * rhobar;
                rhodold = ctildeold * rhobar;
                betad = -stildeold * betad + ctildeold * betahat;

                tautildeold = rhotildeold > (float)0 ? (zetaold - thetatildeold * tautildeold) / rhotildeold : (float)0;
                float taud = rhodold > (float)0 ? (zeta - thetatilde * tautildeold) / rhodold : (float)0;
                dnorm = dnorm + betacheck * betacheck;
                normr = math.sqrt(dnorm + (betad - taud) * (betad - taud) + betadd * betadd);

                // ‖A^T r‖ for the just-updated x = |zetabar| (falls out for free, decreases
                // monotonically). With damping this is the DAMPED normal-equation residual
                // ‖AᵀA x + damp² x − Aᵀb‖ = ‖Aᵀr − damp² x‖.
                if (zetabar * zetabar <= threshold)
                    return LstsqInfoTracked(IterativeSolveStatus.Converged, k + 1, normr, math.abs(zetabar), damp, in x);

                if (!(beta > (float)0) || !(alpha > (float)0)) // NaN-safe: both are norms, nonnegative
