                    return LstsqInfoTracked(IterativeSolveStatus.Breakdown, k + 1, normr, math.abs(zetabar), damp, in x);
            }

            return LstsqInfoTracked(IterativeSolveStatus.MaxIterations, maxIter, normr, math.abs(zetabar), damp, in x);
        }

